        self.tabela_questoes_desativadas.setHorizontalHeaderLabels([
            "#", "Disciplina", "Tópico", "Questão", "Banca", "Ano"
        ])
        self.tabela_questoes_desativadas.setSelectionBehavior(QAbstractItemView.SelectRows)
        self.tabela_questoes_desativadas.setSelectionMode(QAbstractItemView.SingleSelection)
        self.tabela_questoes_desativadas.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.tabela_questoes_desativadas.setAlternatingRowColors(False)
        self.tabela_questoes_desativadas.setShowGrid(False)
        self.tabela_questoes_desativadas.verticalHeader().setVisible(False)
        self.tabela_questoes_desativadas.cellDoubleClicked.connect(
            lambda *_: self.editar_questao_desativada()
        )
        hq = self.tabela_questoes_desativadas.horizontalHeader()
        hq.setSectionResizeMode(0, QHeaderView.ResizeToContents)
        hq.setSectionResizeMode(1, QHeaderView.ResizeToContents)
        hq.setSectionResizeMode(2, QHeaderView.ResizeToContents)
        hq.setSectionResizeMode(3, QHeaderView.Stretch)
        hq.setSectionResizeMode(4, QHeaderView.ResizeToContents)
        hq.setSectionResizeMode(5, QHeaderView.ResizeToContents)
        layout.addWidget(self.tabela_questoes_desativadas, 1)

        acoes = QHBoxLayout()
