                label.setObjectName(
                    "effectivenessImpactLabel"
                )

                if (
                    antes is None
                    or depois is None
                ):
                    texto = "—"
                else:
                    delta = (
                        float(
                            depois
                        )
                        - float(
                            antes
                        )
                    )
                    sinal = (
                        "+"
                        if delta > 0
                        else ""
                    )
                    texto = (
                        f"{float(antes):.1f} → "
                        f"{float(depois):.1f} "
                        f"({sinal}{delta:.1f}{sufixo})"
                    )

                valor = QLabel(
                    texto
                )
                valor.setObjectName(
                    "effectivenessImpactValue"
                )

                frame_layout.addWidget(
                    label
                )
                frame_layout.addWidget(
                    valor
                )

                return frame

