        self.setWindowFlag(
            Qt.WindowMinimizeButtonHint,
            True
        )
        self.setWindowFlag(
            Qt.WindowMaximizeButtonHint,
            True
        )
        self.setWindowModality(Qt.NonModal)
        self.setObjectName("topicDetailsDialog")

        self.topico_id = int(topico_id)
        self.nome_topico = nome_topico
        self.dados_revisoes = []
        self.contexto_topico = obter_contexto_topico(self.topico_id) or {}

        self.setWindowTitle(
            f"Tópico — {nome_topico}"
        )
        self.resize(1120, 720)
        self.setMinimumSize(900, 620)

        # Topic Premium: header independent from the analysis and operational metrics.
