    def selecionar_secao(self, secao="resumo"):
        indice = self._ABAS.get(str(secao), 0)
        self.topico_tabs.setCurrentIndex(indice)
        if indice == self._ABAS["questoes"] and not self._questoes_carregadas_e04:
            self._carregar_questoes_e04()

    def estudar_topico(self):
        # A chamada pode vir inclusive de botoes herdados da visao geral.
        self.selecionar_secao("estudar")

    def ver_questoes_topico(self):
        self.selecionar_secao("questoes")

    def _abrir_configurador_legado(self):
        if topico_esta_pausado(self.topico_id):
            QMessageBox.information(
                self, "Tópico desligado", "Reative o tópico antes de estudar."
            )
            return
        JanelaTopico.estudar_topico(self)

    def _abrir_questoes_legadas(self):
        JanelaTopico.ver_questoes_topico(self)

    def _aplicar_estilo_navegacao(self):
        raiz = self.parentWidget()
        tema = normalizar_tema(getattr(raiz, "tema_atual", "futurista"))
