class SistemaEstudos(QMainWindow):
    dados_alterados = Signal(str)
    estado_foco_alterado = Signal()

    def __init__(self, pre_carregar_startup=False):
        super().__init__()

        self._pre_carregar_startup = bool(pre_carregar_startup)
        self._startup_precarregado = False
        self._topicos_precarregados = {}
        self._topicos_precarregados_data = None
        self._resumo_dia_precarregado = False
        self._resumo_dia_data_referencia = None
        self._calendario_precarregado = False
        self._calendario_data_referencia = None
        self._previsao_semana_suja = True
        self._previsao_semana_data_referencia = None

        # Cache curto + barramento de atualização: evita recalcular o mesmo
        # conjunto analítico várias vezes durante uma única sequência de ações.
        self.cache_analitico = CacheAnalitico(ttl_padrao=12.0)
        self._estado_estatisticas = EstadoEstatisticasLazy()
        self._estado_relatorios = EstadoRelatoriosLazy()
        self._estatisticas_refresh_agendado = False
        self._estatisticas_refresh_em_andamento = False
        self._estatisticas_data_referencia = None

        # Navegação responsiva: Dashboard e Central de Questões mantêm estado
        # de invalidação próprio. Voltar para uma tela já atualizada não deve
        # disparar novamente consultas e montagem de tabelas pesadas.
        self._dashboard_sujo = True
        self._dashboard_refresh_agendado = False
        self._dashboard_data_referencia = None
        self._central_questoes_suja = True
        self._central_questoes_refresh_agendado = False
        self._central_questoes_concurso_id = None
        # Quando a Central é aberta a partir de um tópico, este contexto fica
        # pendente até o carregamento da grade terminar. Isso evita a disputa
        # entre a navegação lazy da Central e a aplicação dos filtros.
        self._central_questoes_contexto_pendente = None
        self._central_questoes_contexto_ativo = None
        self._relatorios_refresh_agendado = False
        self._relatorios_refresh_em_andamento = False

        self._escopos_atualizacao = set()
        self._timer_atualizacao = QTimer(self)
        self._timer_atualizacao.setSingleShot(True)
        self._timer_atualizacao.setInterval(90)
        self._timer_atualizacao.timeout.connect(self._processar_atualizacao_pendente)
        self.dados_alterados.connect(self._receber_alteracao_dados)

        # Tarefas pesadas pós-alteração rodam fora da thread da interface.
        # O debounce evita recomputar várias vezes em uma sequência curta e o
        # warm cache persistente deixa Dashboard/Estatísticas/Relatórios prontos
        # sem empurrar a espera para o primeiro clique.
        self.coordenador_tarefas = CoordenadorTarefas(self)
        self.indicador_tarefa = IndicadorTarefa(self)
        self._tarefa_visual_ativa = None
        self._recalculo_dados_ativo = False
        self._recalculo_dados_reexecutar = False
        self._escopos_recalculo_pendentes = set()
        self._timer_recalculo_dados = QTimer(self)
        self._timer_recalculo_dados.setSingleShot(True)
        self._timer_recalculo_dados.setInterval(450)
        self._timer_recalculo_dados.timeout.connect(self._iniciar_recalculo_dados)
        self._fechamento_solicitado = False
        self._fechamento_em_andamento = False
        self._fechamento_autorizado = False
        # Referência funcional da bateria de questões top-level mais recente.
        # Não há parent Qt entre ela e a principal; esta referência serve só
        # para restauração/atalhos e é limpa ao terminar a sessão.
        self._janela_resolvedor_questoes = None

        self.coordenador_tarefas.iniciada.connect(self._ao_tarefa_iniciada)
        self.coordenador_tarefas.progresso.connect(self._ao_tarefa_progresso)
        self.coordenador_tarefas.concluida.connect(self._ao_tarefa_concluida)
        self.coordenador_tarefas.falhou.connect(self._ao_tarefa_falhou)

        # Proteção preventiva: um banco SQLite corrompido não deve continuar
        # recebendo escritas ou novos backups. A recuperação é feita por uma
        # ferramenta separada, que preserva o arquivo danificado antes de restaurar.
        from backup import ARQUIVO_BANCO
        if ARQUIVO_BANCO.exists():
            banco_ok, banco_msg = verificar_integridade_banco(ARQUIVO_BANCO, completo=False)
            if not banco_ok:
                QMessageBox.critical(
                    self,
                    "Banco de dados precisa de recuperação",
                    (
                        "O Vighna detectou que o estudos.db não está íntegro e bloqueou a abertura para evitar novas gravações.\n\n"
                        f"Arquivo: {ARQUIVO_BANCO}\n\n"
                        f"Diagnóstico: {banco_msg}\n\n"
                        "Feche esta mensagem e execute recuperar_banco.bat na pasta C:\\SistemaEstudos."
                    )
                )
                raise SystemExit(2)

        criar_banco()
        # Compatibilidade 0.29.8: se a versão anterior reagendou uma revisão
        # deliberada recente antes de percorrer todo o banco do tópico,
        # reabre apenas essa rodada. As tentativas permanecem intactas.
        try:
            reabrir_revisoes_parciais_recentes(dias=2)
        except Exception:
            pass

        self.tema_atual = normalizar_tema(
            obter_configuracao_texto(
                "tema_interface",
                "claro"
            )
        )

        # O stylesheet global é aplicado somente depois que a primeira tela
        # estiver montada. Criar centenas de widgets sob um QSS grande faz o
        # Qt recalcular estilo repetidamente e aumenta perceptivelmente o tempo
        # de abertura, sobretudo no executável Windows.

        self.disciplina_atual = None

        self.setWindowTitle(
            f"VighnaStudy {VIGHNA_VERSION}"
        )
        self.resize(1260, 720)
        self.setMinimumSize(
            980,
            620
        )

        self.telas = QStackedWidget()

        # Startup enxuto: somente o Dashboard é construído antes da primeira
        # exibição. As telas secundárias são criadas no primeiro acesso e então
        # permanecem vivas no QStackedWidget pelo restante da execução.
        self.tela_inicial = self.criar_tela_inicial()
        self.telas.addWidget(self.tela_inicial)
        # O03: regiões transparentes sobre as esferas já presentes no GIF.
        # Mantém cards e motores; a abertura dos painéis começa no O04.
        from ui.dashboard_orb_overlay import DashboardOrbOverlay
        self._dashboard_orb_overlay = DashboardOrbOverlay(
            self, self.dashboard_visual_root, self.dashboard_scroll
        )
        self._dashboard_orb_overlay.orbActivated.connect(
            self._dashboard_orb_activated_o03
        )
        # O04: painel flutuante de apresentação, independente dos cards.
        from ui.dashboard_orb_panels import DashboardOrbPanels
        self._dashboard_orb_panels = DashboardOrbPanels(
            self, self.dashboard_visual_root, self.dashboard_scroll
        )
        # L05d: transfere o cabeçalho ORIGINAL (perfil, gerir, central e ajustes)
        # para o Início. Não duplica QComboBox nem seus sinais/conexões.
        # Dashboard histórico conserva os mesmos cards e fica sem cabeçalho.
        self._dashboard_root_layout.removeWidget(self._dashboard_top_container)
        self.tela_portal_inicio = criar_portal_inicio(
            self.voltar_inicio, self.abrir_busca_global, self.abrir_questoes,
            self.abrir_portal_treinos, self.abrir_portal_recursos,
            cabecalho_compartilhado=self._dashboard_top_container,
            abrir_edital=self.abrir_portal_edital,
        )
        self.telas.addWidget(self.tela_portal_inicio)
        aplicar_estilo_portal(self.tela_portal_inicio, self.tema_atual)
        # H36 R1: apenas a apresentação da seção Iniciar Estudo é renovada.
        # A árvore original do Dashboard, métricas e controladores permanecem
        # vivos e ocultos para compatibilidade, histórico e rollback.
        from ui.iniciar_estudo_h36 import instalar_no_dashboard_existente
        instalar_no_dashboard_existente(self)
        # Grade V1: botão adicional na vista H36; página carregada sob demanda.
        # Não altera a recomendação "Começar agora" nem o cadastro de Disciplinas.
        from ui.grade_estudos_v1 import instalar_grade_em_iniciar_estudo
        instalar_grade_em_iniciar_estudo(self)
        # A Central do Edital pertence sempre ao perfil ativo. A estrutura
        # inicial disponibiliza atalhos reais e não presume dados de edital.
        self.tela_portal_edital = criar_portal_edital(
            voltar_inicio=self.abrir_portal_inicio,
            abrir_progresso=self.abrir_progresso_edital,
            abrir_disciplinas=self.abrir_disciplinas_topicos_perfil,
        )
        self.telas.addWidget(self.tela_portal_edital)
        aplicar_estilo_portal_edital(self.tela_portal_edital, self.tema_atual)
        # Migra os três cards executivos originais para Meu Edital.
        # O Planejamento compacto do topo do Dashboard NÃO faz parte.
        self._transferir_cards_dashboard_para_portal_edital()
        # L03: pagina separada, sem modificar o Dashboard ou os motores.
        self.tela_portal_treinos = criar_portal_treinos(
            abrir_inicio=self.abrir_portal_inicio,
            abrir_dashboard=self.voltar_inicio,
            abrir_simulado=lambda: self._abrir_treino_pelo_portal("simulado"),
            abrir_adaptativo=lambda: self._abrir_treino_pelo_portal("adaptativo"),
            abrir_bateria=lambda: self._abrir_treino_pelo_portal("bateria"),
            abrir_revisao=lambda: self._abrir_treino_pelo_portal("revisao"),
            abrir_erros=self.abrir_banco_erros,
            abrir_historico=self.abrir_historico_questoes,
            retomar_sessao=self.abrir_ou_trazer_resolvedor_questoes,
        )
        self.telas.addWidget(self.tela_portal_treinos)
        aplicar_estilo_treinos(self.tela_portal_treinos, self.tema_atual)
        # Transferência real do quadro-mãe; NÃO cria uma segunda instância.
        # A Home e os seis acessos já existentes do portal permanecem intactos.
        self._transferir_quadro_estudo_questoes_para_simulados()
        # L05: catálogo de destinos reais, totalmente independente do banco.
        self.tela_portal_recursos = criar_portal_recursos(
            abrir_inicio=self.abrir_portal_inicio,
            abrir_dashboard=self.voltar_inicio,
            abrir_destinos=self._destinos_portal_recursos(),
        )
        self.telas.addWidget(self.tela_portal_recursos)
        aplicar_estilo_recursos(self.tela_portal_recursos, self.tema_atual)
        # L05h: tela exclusiva de disciplinas, sem replicar o editor de tópicos.
        self.tela_portal_disciplinas = criar_portal_disciplinas(
            listar_disciplinas=listar_disciplinas_gerenciamento,
            listar_topicos=listar_topicos_gerenciamento,
            abrir_disciplina=self.abrir_disciplina,
            editar_disciplinas=self.abrir_disciplinas,
            voltar_inicio=self.abrir_portal_inicio,
        )
        self.telas.addWidget(self.tela_portal_disciplinas)
        aplicar_estilo_portal_disciplinas(self.tela_portal_disciplinas, self.tema_atual)
        self._origem_tela_disciplina = None
        self.telas.setCurrentWidget(self.tela_portal_inicio)
        self.combo_concurso.currentIndexChanged.connect(self._atualizar_perfil_portal)
        self._atualizar_perfil_portal()

        # Shell de navegacao: preserva o QStackedWidget e seus controladores.
        # A barra lateral aparece somente no Futurista; Claro/Escuro seguem
        # visualmente como antes. A estrutura e reversivel por build.
        # O shell passa a compartilhar a mesma ambientação do Dashboard para que
        # as trilhas/ornamentos do tema Futurista também apareçam por trás da
        # barra lateral translúcida.
        self.dashboard_shell = DashboardAmbientCanvas()
        self.dashboard_shell.setObjectName("dashboardAppShell")
        shell_layout = QHBoxLayout(self.dashboard_shell)
        shell_layout.setContentsMargins(0, 0, 0, 0)
        shell_layout.setSpacing(0)
        self.dashboard_sidebar = self._criar_sidebar_dashboard()
        shell_layout.addWidget(self.dashboard_sidebar, 0)
        shell_layout.addWidget(self.telas, 1)
        self.setCentralWidget(self.dashboard_shell)
        self.telas.currentChanged.connect(self._atualizar_selecao_sidebar)
        # GIF do Dashboard avança apenas com a página visível, sem CPU na Home.
        self.telas.currentChanged.connect(self._sincronizar_animacao_dashboard)
        self.combo_concurso.currentIndexChanged.connect(
            self._atualizar_perfil_sidebar
        )
        self._atualizar_perfil_sidebar()
        self._atualizar_layout_sidebar()

        # Aplicar o tema uma única vez sobre a árvore inicial pronta é mais
        # barato do que manter o QSS ativo enquanto milhares de widgets das
        # telas secundárias ainda estão sendo construídos. Telas criadas depois
        # herdam automaticamente o stylesheet da aplicação.
        aplicar_tema(
            QApplication.instance(),
            self.tema_atual
        )

        self.configurar_atalhos_globais()
        self.restaurar_estado_sessao()

        # M25: habilitação assíncrona após montar o Qt; sem apuração na GUI.
        # O worker M09/M10 inicia por QTimer e só publica após COMMIT.
        QTimer.singleShot(0, self._m25_habilitar_merito_producao)

        if not self._pre_carregar_startup:
            # Modo legado/rápido: mostra o Dashboard e atualiza no event loop.
            self._agendar_atualizacao_dashboard(forcar=True)
            self._agendar_backup_abertura()

    # DASHBOARD ALVO — NAVEGACAO LATERAL, LOTE ESTRUTURAL B1
    def _criar_sidebar_dashboard(self):
        """Menu persistente que reutiliza os destinos existentes.

        Inicia recolhido no Futurista e permite expansão manual pelo botão.
        """
        lateral = QFrame()
        lateral.setObjectName("dashboardSidebar")
        lateral.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Expanding)
        coluna = QVBoxLayout(lateral)
        coluna.setContentsMargins(9, 13, 9, 13)
        coluna.setSpacing(5)

        topo = QHBoxLayout()
        self.dashboard_sidebar_marca = QLabel("VighnaStudy")
        self.dashboard_sidebar_marca.setObjectName("dashboardSidebarBrand")
        topo.addWidget(self.dashboard_sidebar_marca, 1)
        self.dashboard_sidebar_toggle = QPushButton("☰")
        self.dashboard_sidebar_toggle.setObjectName("dashboardSidebarToggle")
        self.dashboard_sidebar_toggle.setFixedSize(34, 34)
        self.dashboard_sidebar_toggle.setToolTip("Recolher ou expandir a navegacao lateral")
        self.dashboard_sidebar_toggle.clicked.connect(self._alternar_sidebar_dashboard)
        topo.addWidget(self.dashboard_sidebar_toggle, 0, Qt.AlignRight)
        coluna.addLayout(topo)

        self.dashboard_sidebar_perfil = QLabel("Perfil ativo")
        self.dashboard_sidebar_perfil.setObjectName("dashboardSidebarProfile")
        self.dashboard_sidebar_perfil.setWordWrap(True)
        coluna.addWidget(self.dashboard_sidebar_perfil)

        separador = QFrame()
        separador.setObjectName("dashboardSidebarDivider")
        separador.setFixedHeight(1)
        coluna.addWidget(separador)
        coluna.addSpacing(9)

        # Navegacao consolidada L05f: quatro destinos principais e cinco
        # ferramentas de estudo. As rotas secundarias continuam nas centrais.
        # Icones usam o recurso existente; caracteres sao fallback.
        grupos_navegacao = (
            ("ÁREAS PRINCIPAIS", (
                ("inicio", "Início", "fa6s.house", "⌂", self.abrir_portal_inicio),
                ("dashboard", "Dashboard", "fa6s.chart-column", "▥", self.voltar_inicio),
                ("simulados", "Simulados e Treinos", "fa6s.clipboard-check", "▣", self.abrir_portal_treinos),
                ("recursos", "Central de Recursos", "fa6s.grip", "▦", self.abrir_portal_recursos),
            )),
            ("FERRAMENTAS DE ESTUDO", (
                ("disciplinas", "Disciplinas", "fa6s.book-open", "▣", self.abrir_disciplinas_topicos_perfil),
                ("planejamento", "Planejamento", "fa6s.calendar-days", "▦", self.abrir_calendario),
                ("painel_analitico", "Análises", "fa6s.chart-line", "▥", self.abrir_painel_analitico),
                ("pausa", "Pausa e Desafios", "fa6s.trophy", "☆", self.abrir_pausa_desafios),
            )),
        )
        # Os atalhos centrais rolam apenas quando a altura e pequena (980x620).
        # Configurações continua ancorado ao rodape e acessivel em toda altura.
        nav_scroll = QScrollArea()
        nav_scroll.setObjectName("dashboardSidebarNavigationScroll")
        nav_scroll.setFrameShape(QFrame.NoFrame)
        nav_scroll.setWidgetResizable(True)
        nav_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        # Preserva a rolagem por mouse/touchpad e os tres pontos indicadores.
        nav_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        nav_scroll.setStyleSheet(
            "QScrollArea#dashboardSidebarNavigationScroll { background: transparent; border: none; }"
            "QWidget#dashboardSidebarNavigationContent { background: transparent; }"
        )
        nav_content = QWidget()
        nav_content.setObjectName("dashboardSidebarNavigationContent")
        nav_layout = QVBoxLayout(nav_content)
        nav_layout.setContentsMargins(0, 0, 0, 0)
        nav_layout.setSpacing(5)
        self._sidebar_botoes = {}
        self._sidebar_rotulos = {}
        self._sidebar_icones = {}
        self._sidebar_grupos_rotulos = []
        for indice_grupo, (titulo_grupo, itens) in enumerate(grupos_navegacao):
            if indice_grupo:
                divisoria = QFrame()
                divisoria.setObjectName("dashboardSidebarDivider")
                divisoria.setFixedHeight(1)
                nav_layout.addSpacing(6)
                nav_layout.addWidget(divisoria)
                nav_layout.addSpacing(4)
            rotulo_grupo = QLabel(titulo_grupo)
            rotulo_grupo.setObjectName("dashboardSidebarGroupLabel")
            rotulo_grupo.setFixedHeight(19)
            rotulo_grupo.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)
            rotulo_grupo.setStyleSheet(
                "background: transparent; border: none; padding-left: 4px; "
                "font-size: 8pt; font-weight: 600; "
                f"color: {qss_color('futurista', 'dashboard.subtitle_text')};"
            )
            nav_layout.addWidget(rotulo_grupo)
            self._sidebar_grupos_rotulos.append(rotulo_grupo)
            for chave, rotulo, icone, fallback, acao in itens:
                botao = QPushButton(rotulo)
                botao.setObjectName("dashboardSidebarNavButton")
                botao.setProperty("navSelected", chave == "inicio")
                botao.setFixedHeight(43)
                botao.setCursor(Qt.PointingHandCursor)
                botao.setToolTip(rotulo)
                botao.clicked.connect(lambda _checked=False, fn=acao: fn())
                nav_layout.addWidget(botao)
                self._sidebar_botoes[chave] = botao
                self._sidebar_rotulos[chave] = rotulo
                self._sidebar_icones[chave] = (icone, fallback)
        nav_layout.addStretch(1)
        nav_scroll.setWidget(nav_content)
        self.dashboard_sidebar_nav_scroll = nav_scroll
        self.dashboard_sidebar_scroll_dots = SidebarNavigationDots(
            nav_scroll.verticalScrollBar(), nav_scroll.viewport()
        )
        coluna.addWidget(nav_scroll, 1)

        # PERFIL CANDIDATO P01: acesso global, independente do perfil de edital.
        # Fica no rodape para continuar acessivel com a navegacao recolhida.
        botao_perfil_candidato = QPushButton("Perfil do Candidato")
        botao_perfil_candidato.setObjectName("dashboardSidebarNavButton")
        botao_perfil_candidato.setProperty("navSelected", False)
        botao_perfil_candidato.setFixedHeight(43)
        botao_perfil_candidato.setCursor(Qt.PointingHandCursor)
        botao_perfil_candidato.setToolTip("Abrir Perfil do Candidato")
        botao_perfil_candidato.setAccessibleName("Abrir Perfil do Candidato")
        botao_perfil_candidato.clicked.connect(self.abrir_perfil_candidato)
        coluna.addWidget(botao_perfil_candidato)
        self._sidebar_botoes["perfil_candidato"] = botao_perfil_candidato
        self._sidebar_rotulos["perfil_candidato"] = "Perfil do Candidato"
        self._sidebar_icones["perfil_candidato"] = ("fa6s.id-card", "◉")

        # Busca global fixa no rodape, acima das configuracoes.
        # Compartilha o mesmo controlador de pesquisa do atalho Ctrl+K
        # e acompanha o estado expandido/recolhido da barra lateral.
        botao_pesquisa = QPushButton("Pesquisar")
        botao_pesquisa.setObjectName("dashboardSidebarNavButton")
        botao_pesquisa.setProperty("navSelected", False)
        botao_pesquisa.setFixedHeight(43)
        botao_pesquisa.setCursor(Qt.PointingHandCursor)
        botao_pesquisa.setToolTip("Pesquisar (Ctrl+K)")
        botao_pesquisa.setAccessibleName("Abrir busca global (Ctrl+K)")
        botao_pesquisa.clicked.connect(self.abrir_busca_global)
        coluna.addWidget(botao_pesquisa)
        self._sidebar_botoes["pesquisa"] = botao_pesquisa
        self._sidebar_rotulos["pesquisa"] = "Pesquisar"
        self._sidebar_icones["pesquisa"] = ("fa5s.search", "⌕")

        botao_config = QPushButton("Configurações")
        botao_config.setObjectName("dashboardSidebarNavButton")
        botao_config.setProperty("navSelected", False)
        botao_config.setFixedHeight(43)
        botao_config.setCursor(Qt.PointingHandCursor)
        botao_config.setToolTip("Configurações")
        botao_config.clicked.connect(self.abrir_configuracoes)
        coluna.addWidget(botao_config)
        self._sidebar_botoes["configuracoes"] = botao_config
        self._sidebar_rotulos["configuracoes"] = "Configurações"
        self._sidebar_icones["configuracoes"] = ("fa6s.gear", "⚙")
        # A navegação Futurista inicia recolhida a cada abertura. O botão
        # continua permitindo alternar entre os estados durante a sessão.
        self._sidebar_expandida_manual = False
        self._sidebar_expandida_efetiva = None
        return lateral

    # PERFIL CANDIDATO M04: estrutura visual, sem vinculo academico nesta fase.
    # O brasao principal permanece ausente ate existir meritacao global validada.
    def _perfil_m04_pixmap(self, marco, tamanho):
        tabela = getattr(self, "_perfil_m04_cache_png", None)
        if tabela is None:
            tabela = {}
            self._perfil_m04_cache_png = tabela
        marco = int(marco)
        if marco not in tabela:
            brutos = base64.b64decode(_PERFIL_BRASOES_M35_ORIGINAIS_VISUAIS[marco])
            imagem = QPixmap()
            if not imagem.loadFromData(brutos, "PNG"):
                raise ValueError("Imagem do brasao nao pode ser carregada")
            tabela[marco] = imagem
        return tabela[marco].scaled(
            tamanho, tamanho, Qt.KeepAspectRatio, Qt.SmoothTransformation
        )

    def _perfil_m04_nome_atual(self):
        # Identidade de exibicao separada do perfil de concurso/edital.
        return str(QSettings("VighnaStudy", "PerfilCandidato").value(
            "nome_exibicao", "Candidato"
        ) or "Candidato").strip()[:60] or "Candidato"

    def _perfil_m04_salvar_nome(self):
        campo = getattr(self, "_perfil_m04_campo_nome", None)
        if campo is None:
            return
        nome = campo.text().strip()[:60] or "Candidato"
        campo.setText(nome)
        QSettings("VighnaStudy", "PerfilCandidato").setValue(
            "nome_exibicao", nome
        )

    def abrir_perfil_candidato(self):
        pagina = getattr(self, "tela_perfil_candidato", None)
        if pagina is None:
            pagina = QWidget()
            pagina.setObjectName("perfilCandidatoPagina")
            raiz = QVBoxLayout(pagina)
            raiz.setContentsMargins(30, 25, 30, 25)
            raiz.setSpacing(15)
            linha_titulo = QHBoxLayout()
            titulo = QLabel("Perfil do Candidato")
            titulo.setObjectName("perfilCandidatoTitulo")
            linha_titulo.addWidget(titulo, 1)
            voltar = QPushButton("Voltar ao Início")
            voltar.setObjectName("perfilCandidatoVoltar")
            voltar.setCursor(Qt.PointingHandCursor)
            voltar.clicked.connect(self.abrir_portal_inicio)
            linha_titulo.addWidget(voltar)
            raiz.addLayout(linha_titulo)

            painel = QFrame()
            painel.setObjectName("perfilCandidatoPainel")
            cabecalho = QHBoxLayout(painel)
            cabecalho.setContentsMargins(24, 18, 24, 18)
            cabecalho.setSpacing(20)
            icone = QLabel("◇")
            icone.setObjectName("perfilCandidatoBrasao")
            icone.setFixedSize(122, 122)
            icone.setAlignment(Qt.AlignCenter)
            icone.setToolTip("Brasao de merito: aguardando apuracao do historico global")
            icone.setAccessibleName("Brasao de merito ainda nao atribuido")
            cabecalho.addWidget(icone)
            self._perfil_m04_icone_atual = icone

            identidade = QVBoxLayout()
            identidade.setSpacing(8)
            legenda = QLabel("IDENTIDADE DO CANDIDATO")
            legenda.setObjectName("perfilCandidatoChamada")
            identidade.addWidget(legenda)
            nome = QLineEdit(self._perfil_m04_nome_atual())
            nome.setObjectName("perfilCandidatoNome")
            nome.setMaxLength(60)
            nome.setPlaceholderText("Nome de exibicao")
            nome.setToolTip("Nome para exibir no perfil; nao altera concursos")
            nome.editingFinished.connect(self._perfil_m04_salvar_nome)
            self._perfil_m04_campo_nome = nome
            identidade.addWidget(nome)
            estado = QLabel("Brasao e saldo: aguardando validacao do historico global")
            estado.setObjectName("perfilCandidatoSubtitulo")
            estado.setWordWrap(True)
            identidade.addWidget(estado)
            self._perfil_m04_estado = estado
            cabecalho.addLayout(identidade, 1)
            raiz.addWidget(painel)

            # Indicadores ficam abaixo do cabeçalho, nunca sob a insígnia.
            faixa_merito = QFrame()
            faixa_merito.setObjectName("perfilCandidatoFaixaMeritoM05")
            faixa_layout = QVBoxLayout(faixa_merito)
            faixa_layout.setSpacing(7)
            dados_global = QLabel("Saldo global: ainda não apurado")
            dados_global.setObjectName("perfilCandidatoDadosM05")
            self._perfil_m05_dados_global = dados_global
            faixa_layout.addWidget(dados_global)
            proximo = QLabel("Próximo marco: aguardando apuração")
            proximo.setObjectName("perfilCandidatoProximoM05")
            self._perfil_m05_proximo_marco = proximo
            faixa_layout.addWidget(proximo)
            barra = QProgressBar()
            barra.setObjectName("perfilCandidatoProgressoM05")
            barra.setRange(0, 100)
            barra.setTextVisible(False)
            barra.setFixedHeight(9)
            barra.hide()
            self._perfil_m05_barra_progresso = barra
            faixa_layout.addWidget(barra)
            raiz.addWidget(faixa_merito)

            botoes = QHBoxLayout()
            botoes.setSpacing(12)
            ver = QPushButton("Ver catálogo de brasões")
            ver.setObjectName("perfilCandidatoCatalogo")
            ver.setCursor(Qt.PointingHandCursor)
            ver.clicked.connect(self._perfil_m04_abrir_catalogo)
            botoes.addWidget(ver)
            botoes.addStretch(1)
            raiz.addLayout(botoes)
            informativo = QLabel(
                "O catálogo apresenta as 12 conquistas e seus requisitos. "
                "Nenhum marco será considerado desbloqueado antes da auditoria acadêmica."
            )
            informativo.setObjectName("perfilCandidatoSubtitulo")
            informativo.setWordWrap(True)
            raiz.addWidget(informativo)
            raiz.addStretch(1)

            self.tela_perfil_candidato = pagina
            self.telas.addWidget(pagina)
        self._perfil_m04_campo_nome.setText(self._perfil_m04_nome_atual())
        self._perfil_m05_atualizar_painel()
        self._estilizar_perfil_candidato()
        self.telas.setCurrentWidget(pagina)

    # MÉRITO M08 — fonte única para Perfil, catálogo e Bateria de Questões.
    # O adaptador acadêmico real ainda não está conectado (banco.py pendente).
    def _m08_coordenador_atual(self):
        coordenador = getattr(self, "_m08_coordenador", None)
        if coordenador is None:
            from ui.merito.sincronizacao_merito_m08 import CoordenadorMeritoM08
            coordenador = CoordenadorMeritoM08()
            self._m08_coordenador = coordenador
        return coordenador

    def _m08_estado_atual(self):
        return self._m08_coordenador_atual().snapshot()

    def _m08_distribuir_estado(self, estado):
        """Entrega snapshot imutável a uma eventual bateria já aberta."""
        self._perfil_m05_atualizar_painel()
        janela = self.obter_janela_resolvedor_questoes()
        receber = getattr(janela, "_m08_receber_estado_sincronizado", None)
        if callable(receber):
            receber(estado)

    def _m08_publicar_integracao_auditada(self, resultado):
        """Publicação explícita: apenas ResultadoIntegracao M03 validado.

        Não busca histórico, não executa polling nem toca no banco.
        """
        estado, mudou = self._m08_coordenador_atual().publicar(resultado)
        if mudou:
            self._m08_distribuir_estado(estado)
        return estado

    def _m08_invalidar_merito_global(self, motivo):
        """Revoga exibição quando o snapshot deixa de ser confiável."""
        estado, mudou = self._m08_coordenador_atual().invalidar(motivo)
        if mudou:
            self._m08_distribuir_estado(estado)
        return estado

    # M25 — ativação estrita com banco acadêmico oficial e perfil durável.
    # Nunca aceita override de estudos.db ou identidade por variável de ambiente.
    def _m25_habilitar_merito_producao(self):
        if getattr(self, "_m13_ponte_qt", None) is not None:
            return False
        try:
            from ui.merito.ativacao_producao_m25 import preparar_escopo_producao_m25
            from ui.merito.ponte_qt_merito_m15 import PonteMeritoQtM15
            escopo = preparar_escopo_producao_m25()
            ponte = PonteMeritoQtM15(self, escopo, clone_autorizado=False)
            self._m13_ponte_qt = ponte
            return True
        except Exception:
            # Falha fechada: sem insígnia até a próxima inicialização auditada.
            # Não interferir nas questões nem no backup acadêmico existente.
            try:
                self._m08_invalidar_merito_global("Mérito: origem não validada")
            except Exception:
                pass
            return False

    # MÉRITO M13 — ponte Qt OBRIGATORIAMENTE DESATIVADA por padrão.
    # Não há import PySide6 adicional, banco de mérito ou tarefa ao iniciar o app.
    def _m13_habilitar_clone_laboratorio(self, escopo, *,
                                        pasta_identidade, banco_py_clone,
                                        banco_py_referencia, autorizado_clone=False):
        """Habilitação manual EXCLUSIVAMENTE em clone isolado e auditado.

        Chamada proibida na distribuição final até revisão do esquema e build
        Windows. É preciso definir VIGHNA_M13_CLONE_LAB=CONFIRMADO e fornecer
        confirmação expressa, identidade existente e fonte banco.py idêntica
        à referência. Nunca criar automaticamente uma identidade nova.
        """
        if os.environ.get("VIGHNA_M13_CLONE_LAB") != "CONFIRMADO" or autorizado_clone is not True:
            raise RuntimeError("M13 bloqueado: somente clone autorizado")
        from ui.merito.integracao_merito_m11 import EscopoM11
        from ui.merito.identidade_candidato_m12 import obter_identidade
        if not isinstance(escopo, EscopoM11) or escopo.modo != "laboratorio":
            raise RuntimeError("Escopo M13 não é laboratório")
        from backup import ARQUIVO_BANCO
        copia = Path(escopo.banco_academico).resolve(strict=True)
        original = Path(ARQUIVO_BANCO).resolve(strict=False)
        if copia == original or (original.exists() and copia.samefile(original)):
            raise RuntimeError("M13 nunca pode abrir o banco acadêmico da instalação")
        diretorio_clone = Path(escopo.banco_merito).parent.resolve(strict=False)
        if not diretorio_clone.is_dir():
            raise RuntimeError("Pasta lateral de mérito do clone precisa existir")
        if Path(pasta_identidade).resolve(strict=False) != diretorio_clone:
            raise RuntimeError("Identidade deve residir na pasta lateral do próprio clone")
        if Path(__file__).resolve().parent in diretorio_clone.parents or diretorio_clone == Path(__file__).resolve().parent:
            raise RuntimeError("Não gravar mérito sob a instalação do aplicativo")
        identidade = obter_identidade(pasta_identidade)
        if identidade.perfil_id != escopo.perfil_id:
            raise RuntimeError("Identidade persistente não corresponde ao escopo")
        from hashlib import sha256
        fonte_atual = Path(banco_py_clone).resolve(strict=True)
        fonte_ref = Path(banco_py_referencia).resolve(strict=True)
        if fonte_atual == Path(__file__).with_name("banco.py").resolve(strict=False):
            raise RuntimeError("Fonte indicada é o banco.py da instalação, não o clone")
        digest_conhecido = "3f32c1b291ca9781c8572baaaa21f90eb64095d21e2cb4e17c17c3ddb53ae0f8"
        if (sha256(fonte_atual.read_bytes()).hexdigest() != digest_conhecido or
                sha256(fonte_ref.read_bytes()).hexdigest() != digest_conhecido):
            raise RuntimeError("banco.py divergente do SHA-256 homologado para o laboratório")
        from ui.merito.inspecao_schema_m12 import inspecionar_schema
        diagnostico_schema = inspecionar_schema(copia)
        if not diagnostico_schema.compativel:
            raise RuntimeError("Esquema acadêmico do clone incompatível: integração bloqueada")
        if getattr(self, "_m13_ponte_qt", None) is not None:
            raise RuntimeError("Ponte M13 já habilitada")
        # M15 — pool de apuração dedicado e encerramento seguro no clone.
        from ui.merito.ponte_qt_merito_m15 import PonteMeritoQtM15
        ponte = PonteMeritoQtM15(self, escopo, clone_autorizado=True)
        self._m13_ponte_qt = ponte
        return ponte

    def _m15_aguardar_merito_antes_fechamento(self):
        """Não iniciar backup final enquanto apuração lateral estiver em curso.

        Não lê nem grava SQLite; consulta apenas o pool Qt dedicado.
        """
        ponte = getattr(self, "_m13_ponte_qt", None)
        if ponte is None:
            return True
        preparar = getattr(ponte, "iniciar_encerramento", None)
        if not callable(preparar):
            raise RuntimeError("Ponte sem protocolo M15: fechamento seguro bloqueado")
        if not getattr(self, "_m15_sinal_encerramento_conectado", False):
            ponte.encerramento_pronto.connect(self._m15_retomar_fechamento, Qt.QueuedConnection)
            self._m15_sinal_encerramento_conectado = True
        return preparar()

    def _m15_retomar_fechamento(self):
        """Sinal Qt em GUI: retoma fechamento legado uma vez confirmado o pool."""
        if (getattr(self, "_fechamento_solicitado", False)
                and not getattr(self, "_fechamento_em_andamento", False)
                and not getattr(self, "_fechamento_autorizado", False)):
            self._executar_tarefa_fechamento()

    def _m13_registrar_tentativa_academica(self, tentativa_id, *, simulado_aberto):
        ponte = getattr(self, "_m13_ponte_qt", None)
        if ponte is not None:
            try:
                return ponte.registrar_tentativa(tentativa_id, simulado_aberto=simulado_aberto)
            except Exception:
                self._m13_revogar_em_falha("Falha ao registrar evento de mérito")
        return False

    def _m13_simulado_entregue(self):
        ponte = getattr(self, "_m13_ponte_qt", None)
        if ponte is not None:
            try:
                return ponte.simulado_entregue(concluida=True, commit_ok=True)
            except Exception:
                self._m13_revogar_em_falha("Falha ao publicar entrega do simulado")
        return False

    def _m13_revogar_em_falha(self, motivo):
        ponte = getattr(self, "_m13_ponte_qt", None)
        if ponte is not None:
            try:
                ponte.revogar(motivo)
            except Exception:
                self._m08_invalidar_merito_global(motivo)

    # Entrada legada M05 agora encaminha obrigatoriamente ao M08.
    def _perfil_m05_receber_integracao_auditada(self, resultado):
        return self._m08_publicar_integracao_auditada(resultado)

    def _perfil_m05_visao_atual(self):
        return self._m08_estado_atual().visao

    def _perfil_m05_atualizar_painel(self):
        if not hasattr(self, "_perfil_m04_icone_atual"):
            return
        visao = self._perfil_m05_visao_atual()
        icone = self._perfil_m04_icone_atual
        progresso = getattr(self, "_perfil_m05_barra_progresso", None)
        dados = getattr(self, "_perfil_m05_dados_global", None)
        seguinte = getattr(self, "_perfil_m05_proximo_marco", None)
        if not visao.apurado:
            icone.clear()
            icone.setText("◇")
            icone.setToolTip("Brasão ainda não atribuído: aguardando histórico global auditado")
            icone.setAccessibleName("Brasão de mérito ainda não atribuído")
            self._perfil_m04_estado.setText("Mérito global: aguardando apuração do histórico completo")
            if dados is not None:
                dados.setText("Saldo global: ainda não apurado")
            if seguinte is not None:
                seguinte.setText("Próximo marco: aguardando apuração")
            if progresso is not None:
                progresso.setVisible(False)
            return
        if visao.brasao_atual:
            icone.setText("")
            icone.setPixmap(self._perfil_m04_pixmap(visao.brasao_atual, 116))
            icone.setToolTip("Brasão de mérito conquistado")
            icone.setAccessibleName("Brasão conquistado do candidato")
        else:
            icone.clear()
            icone.setText("◇")
            icone.setToolTip("Nenhum brasão conquistado até o momento")
        self._perfil_m04_estado.setText("Mérito baseado no histórico acadêmico global auditado")
        if dados is not None:
            dados.setText("Saldo global: {:+,}   |   Recorde: {:+,}".format(
                visao.saldo, visao.recorde).replace(",", "."))
        if seguinte is not None:
            if visao.proximo_marco is None:
                seguinte.setText("Todos os 12 brasões conquistados")
            else:
                seguinte.setText("Próximo marco: +{:,.0f}   •   Faltam {:,} pontos".format(
                    visao.proximo_marco, visao.faltam).replace(",", "."))
        if progresso is not None:
            progresso.setVisible(visao.proximo_marco is not None)
            progresso.setValue(int(round(visao.progresso_pct or 0)))

    def _perfil_m04_abrir_catalogo(self):
        janela = QDialog(self)
        janela.setWindowTitle("Catálogo de Brasões de Mérito")
        janela.resize(980, 655)
        janela.setMinimumSize(720, 490)
        raiz = QVBoxLayout(janela)
        titulo = QLabel("CATÁLOGO DE BRASÕES")
        titulo.setObjectName("catalogoTituloM04")
        raiz.addWidget(titulo)
        visao = self._perfil_m05_visao_atual()
        if visao.apurado:
            descricao = "Conquistas globais auditadas • os marcos conquistados são permanentes"
        else:
            descricao = "Prévia visual • requisitos oficiais • desbloqueios ainda não apurados"
        nota = QLabel(descricao)
        nota.setWordWrap(True)
        nota.setObjectName("catalogoNotaM04")
        raiz.addWidget(nota)
        rolagem = QScrollArea()
        rolagem.setWidgetResizable(True)
        rolagem.setFrameShape(QFrame.NoFrame)
        rolagem.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        conteudo = QWidget()
        grade = QGridLayout(conteudo)
        grade.setContentsMargins(7, 7, 7, 7)
        grade.setSpacing(12)
        for indice, cartao in enumerate(visao.cartoes):
            marco = cartao.marco
            bloco = QFrame()
            bloco.setObjectName("catalogoBrasaoCardM04")
            coluna = QVBoxLayout(bloco)
            coluna.setContentsMargins(8, 12, 8, 12)
            coluna.setSpacing(6)
            figura = QLabel()
            figura.setAlignment(Qt.AlignCenter)
            figura.setMinimumHeight(137)
            figura.setPixmap(self._perfil_m04_pixmap(marco, 134))
            if cartao.estado == "bloqueado":
                from PySide6.QtWidgets import QGraphicsOpacityEffect
                filtro = QGraphicsOpacityEffect(figura)
                filtro.setOpacity(0.42)
                figura.setGraphicsEffect(filtro)
            coluna.addWidget(figura)
            nome = QLabel(_PERFIL_NOMES_M04[marco])
            nome.setAlignment(Qt.AlignCenter)
            nome.setWordWrap(True)
            nome.setObjectName("catalogoNomeM04")
            coluna.addWidget(nome)
            meta = QLabel(f"Marco: +{marco:,}".replace(",", "."))
            meta.setAlignment(Qt.AlignCenter)
            meta.setObjectName("catalogoMarcoM04")
            coluna.addWidget(meta)
            if cartao.estado == "conquistado":
                situacao = "Conquistado" + (" • Brasão atual" if cartao.destaque_atual else "")
            elif cartao.estado == "bloqueado":
                situacao = "Bloqueado"
            else:
                situacao = "Aguardando apuração"
            status = QLabel(situacao)
            status.setAlignment(Qt.AlignCenter)
            status.setObjectName("catalogoEstadoM04")
            coluna.addWidget(status)
            grade.addWidget(bloco, indice // 3, indice % 3)
        rolagem.setWidget(conteudo)
        raiz.addWidget(rolagem, 1)
        fechar = QPushButton("Fechar")
        fechar.setCursor(Qt.PointingHandCursor)
        fechar.clicked.connect(janela.accept)
        raiz.addWidget(fechar, 0, Qt.AlignRight)

        tema = normalizar_tema(getattr(self, "tema_atual", "claro"))
        if tema == "claro":
            fundo, cartao, borda = "#F1F5F9", "#FFFFFF", "#B4C7DA"
            texto, secundario, acento = "#18324B", "#62778B", "#1D74A3"
        elif tema == "futurista":
            fundo, cartao, borda = "#07142A", "#10243B", "#2C7799"
            texto, secundario, acento = "#E8F4FC", "#A7C1D1", "#6DDDF4"
        else:
            fundo, cartao, borda = "#101924", "#1E2C3B", "#416079"
            texto, secundario, acento = "#E7F1FA", "#ACBDCD", "#72CBE9"
        janela.setStyleSheet(f"""
            QDialog {{ background: {fundo}; }}
            QLabel {{ color: {texto}; background: transparent; }}
            QLabel#catalogoTituloM04 {{ font-size: 17pt; font-weight: 700; color: {acento}; }}
            QLabel#catalogoNotaM04 {{ color: {secundario}; font-size: 10pt; }}
            QScrollArea {{ background: transparent; border: none; }}
            QScrollArea > QWidget > QWidget {{ background: transparent; }}
            QFrame#catalogoBrasaoCardM04 {{ background: {cartao}; border: 1px solid {borda}; border-radius: 11px; }}
            QFrame#catalogoBrasaoCardM04 QLabel {{ border: none; background: transparent; }}
            QLabel#catalogoNomeM04 {{ font-weight: 600; font-size: 10pt; }}
            QLabel#catalogoMarcoM04 {{ color: {acento}; font-weight: 600; }}
            QLabel#catalogoEstadoM04 {{ color: {secundario}; font-size: 9pt; }}
            QPushButton {{ background: {cartao}; color: {texto}; border: 1px solid {borda}; border-radius: 8px; padding: 9px 14px; }}
            QPushButton:hover {{ border-color: {acento}; }}
        """)
        janela.exec()

