        foco_hoje_layout.addWidget(self.dashboard_iniciar_foco)
        # Camada visual acima do fundo/barra, sem capturar o mouse.
        foco_arte_reserva.raise_()

        # ----------------------------------------------------
        # Seu progresso — bloco visual em quatro faixas:
