        progresso_layout = QVBoxLayout(progresso_card)
        progresso_layout.setContentsMargins(14, 11, 14, 10)
        progresso_layout.setSpacing(7)

        # Faixa 1: título e subtítulo sem cruzar com o conteúdo de XP.
