        def criar_linha_foco(titulo_texto, role):
            frame = QFrame()
            frame.setObjectName(
                "dashboardRhythmLine"
            )
            frame.setProperty(
                "metricRole",
                role
            )
            linha = QHBoxLayout(frame)
            linha.setContentsMargins(3, 4, 3, 4)
            linha.setSpacing(7)
            ponto = QLabel("●")
            ponto.setObjectName(
                "dashboardRhythmDot"
            )
            rotulo = QLabel(titulo_texto)
            rotulo.setObjectName(
                "dashboardRhythmLineLabel"
            )
            valor = QLabel("0")
            valor.setObjectName(
                "dashboardRhythmLineValue"
            )
            valor.setAlignment(
                Qt.AlignRight | Qt.AlignVCenter
            )
            linha.addWidget(ponto)
            linha.addWidget(rotulo)
            linha.addStretch()
            linha.addWidget(valor)
            return frame, valor

