        def criar_metrica_semanal(
            chave,
            titulo_texto
        ):
            card = QFrame()
            card.setObjectName(
                "weeklyGoalMetric"
            )

            card_layout = QVBoxLayout(
                card
            )
            card_layout.setContentsMargins(
                10,
                7,
                10,
                7
            )
            card_layout.setSpacing(
                3
            )

            titulo_label = QLabel(
                titulo_texto
            )
            titulo_label.setObjectName(
                "weeklyGoalMetricTitle"
            )

            valor_label = QLabel(
                "—"
            )
            valor_label.setObjectName(
                "weeklyGoalValue"
            )

            barra = QProgressBar()
            barra.setObjectName(
                "weeklyGoalProgress"
            )
            barra.setRange(
                0,
                100
            )
            barra.setValue(
                0
            )
            barra.setTextVisible(
                False
            )
            barra.setFixedHeight(
                6
            )

            dica = QLabel(
                "Meta desativada"
            )
            dica.setObjectName(
                "weeklyGoalHint"
            )

            card_layout.addWidget(
                titulo_label
            )
            card_layout.addWidget(
                valor_label
            )
            card_layout.addWidget(
                barra
            )
            card_layout.addWidget(
                dica
            )

            self.metas_semanais_widgets[
                chave
            ] = {
                "card": card,
                "valor": valor_label,
                "barra": barra,
                "dica": dica,
            }

            return card

