        self.questoes_editar_lote.setEnabled(False)

        # VIGHNA_CENTRAL_CV03_R1 — pesquisa prioritária, listagem moderada e sem prévia.
        # Somente apresentação local; preserva os controladores e o banco existentes.
        tela.setObjectName("questionsCentralPage")
        layout.setContentsMargins(16, 11, 16, 12)
        layout.setSpacing(9)
        subtitulo.setText("Pesquise, organize e gerencie seu banco de questões.")
        subtitulo.setVisible(True)
        titulo.setMinimumHeight(29)
        cabecalho.setSpacing(10)

        # Remove a faixa administrativa redundante, preservando os três comandos reais.
        layout.removeWidget(painel_admin)
        for _cv03_widget in (nova, importar, mais):
            painel_admin_layout.removeWidget(_cv03_widget)
        painel_admin.hide()
        for _cv03_widget in (nova, importar, mais):
            _cv03_widget.setFixedHeight(34)
        nova.setMinimumWidth(128)
        importar.setMinimumWidth(94)
        mais.setMinimumWidth(75)

        # Inventário permanece completo, mas com leitura e bordas discretas.
        inventario.setMinimumHeight(66)
        inventario.setMaximumHeight(76)
        inventario_layout.setContentsMargins(9, 7, 9, 7)
        for _cv03_i in range(inventario_layout.count()):
            _cv03_w = inventario_layout.itemAt(_cv03_i).widget()
            if _cv03_w is not None and _cv03_w.objectName() == "questionsInventoryItem":
                _cv03_w.layout().setContentsMargins(10, 3, 10, 3)
                _cv03_w.layout().setSpacing(2)

        # A pesquisa é o primeiro módulo da área de trabalho.
        area_trabalho_layout.setContentsMargins(10, 9, 10, 9)
        area_trabalho_layout.setSpacing(7)
        for _cv03_item in (secao_lista, filtros, self.tabela_questoes):
            area_trabalho_layout.removeWidget(_cv03_item)
        for _cv03_layout in (acoes, paginacao):
            area_trabalho_layout.removeItem(_cv03_layout)

        filtros_layout.setContentsMargins(12, 9, 12, 9)
        filtros_layout.setSpacing(7)
        _cv03_cabecalho_busca = QHBoxLayout()
        _cv03_cabecalho_busca.setSpacing(8)
        _cv03_titulo_busca = QLabel("Localizar questões")
