    def atualizar_ajuda_aba_estatisticas(self, *args):
        if not hasattr(self, "abas_estatisticas"):
            return
        if not hasattr(self, "estatisticas_ajuda"):
            return
        indice = self.abas_estatisticas.currentIndex()
        nome = self.abas_estatisticas.tabText(indice) if indice >= 0 else "Estatísticas"
        descricao = self.descricoes_abas_estatisticas().get(
            nome,
            "Esta aba reúne indicadores e análises do perfil ativo."
        )
        self.estatisticas_ajuda.setToolTip(
            f"{nome}\n\n{descricao}\n\nClique para ver a explicação completa."
        )

    def mostrar_ajuda_aba_estatisticas(self):
        indice = self.abas_estatisticas.currentIndex()
